from robot.libraries.BuiltIn import BuiltIn

from taf.rfrl.procedures.resources.python.logger import log_env_state
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine


class CustomConfig:
    """
    Class to handle custom testline configuration. Two global variables are used here,
    both initialized during Common Suite Setup:
    - default_tl - the default configuration object, which is the default configuration for the testline
    - tl - the configuration that is currently being used (same as default_tl if no custom config is used,
                    different otherwise).
    """
    def __init__(self):
        """
        Initializes the CustomConfig object.
        """
        self._test_line = TestLine()

    @property
    def default_config(self):
        """
        Returns default configuration object (default_tl) from the init file
        :returns: default configuration object
        :rtype: TestlLine()
        """
        return BuiltIn().get_variable_value('${default_tl}')

    @property
    def custom_config(self):
        """
        Returns custom configuration object (tl) from the init file
        :returns: custom configuration object
        :rtype: TestlLine()
        """
        return BuiltIn().get_variable_value('${tl}')

    def get_serial_numbers_of_unused_rmods(self, bts_type="GNB"):
        """
        Compares objects of default_config with those of custom_config and returns
        serial numbers of RMODs that will not be used within the use of custom_config

        :param bts_type: node type ENB/GNB
        """
        all_serial_numbers = self._get_serial_numbers_of_rmods(config=self.default_config, bts_type=bts_type)
        serial_numbers_in_custom = self._get_serial_numbers_of_rmods(config=self.custom_config, bts_type=bts_type)
        return [serial_number for serial_number in all_serial_numbers if serial_number not in serial_numbers_in_custom]

    def _get_serial_numbers_of_rmods(self, config, bts_type):
        serial_numbers = []
        if bts_type == "GNB":
            serial_numbers.extend(self._test_line.get_serial_numbers_of_all_rmods_from_init(custom_init=config))
        elif bts_type == "ENB":
            try:
                serial_numbers.extend(self._test_line.get_serial_numbers_of_all_rmods_from_init(bts_type='ENB',
                                                                                                custom_init=config))
            except TypeError:
                serial_numbers.extend(self._test_line.get_serial_numbers_of_all_rmods_from_init(custom_init=config))
        serial_numbers = list(set(serial_numbers))
        log_env_state("Serial numbers of RMODs read from init file: {}".format(serial_numbers))
        return serial_numbers
